#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM${e}[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# Project root: where .env is written and where the Vercel CLI runs. Defaults
# to the repository this script lives in (scripts/..).
# Override with:  PROJECT_DIR=/path/to/repo bash scripts/setup-wizard.sh
PROJECT_DIR="${PROJECT_DIR:-$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)}"
# The Vercel project to link (stage 13) and, optionally, the team/scope it
# lives in. Override with VERCEL_PROJECT=... VERCEL_SCOPE=...
VERCEL_PROJECT="${VERCEL_PROJECT:-family-expenses}"
VERCEL_SCOPE="${VERCEL_SCOPE:-}"
[[ "$ENV_FILE" == ".env" ]] && ENV_FILE="$PROJECT_DIR/.env"

# ask_required KEY "Prompt": like ask, but re-asks while the answer is blank.
ask_required() {
  while :; do
    ask "$1" "$2" || return 1
    [[ -n "${!1}" ]] && return 0
    warn "this value is required"
  done
}

# ask_secret_required KEY "Prompt": like ask_secret, but re-asks while blank.
ask_secret_required() {
  while :; do
    ask_secret "$1" "$2" || return 1
    [[ -n "${!1}" ]] && return 0
    warn "this value is required"
  done
}

# push_vercel_env NAME VALUE ENVIRONMENT [extra vercel flags...] upserts one
# Vercel env var (--force overwrites, value goes in via stdin so it never
# appears in argv). Records a failure in SKIPPED instead of aborting.
push_vercel_env() {
  local name="$1" value="$2" environment="$3" out line
  shift 3
  if out=$(printf '%s' "$value" | vercel --cwd "$PROJECT_DIR" env add "$name" \
             --environment "$environment" --yes --force "$@" 2>&1); then
    printf '  %s✓ pushed%s %s → Vercel %s\n' "$GREEN" "$RESET" "$name" "$environment"
  else
    warn "could not push $name to Vercel $environment:"
    while IFS= read -r line; do note "    $line"; done <<< "$(printf '%s\n' "$out" | tail -n 3)"
    SKIPPED+=("Vercel env $name ($environment): vercel env add $name --environment $environment --force")
  fi
}

run_wizard() {

TOTAL_STAGES=14

if [[ ! -d "$PROJECT_DIR" ]]; then
  warn "project directory not found: $PROJECT_DIR  (set PROJECT_DIR=... and re-run)"
  exit 1
fi
if ! command -v openssl >/dev/null 2>&1; then
  warn "openssl is required (it generates FAMILY_ACCESS_CODE and JWT_SECRET locally)"
  exit 1
fi

banner "Family Expense Manager setup"

# ── 1. Google Drive folder ───────────────────────────────────────────────
stage "Google Drive: the Expense Manager folder"
say "Everything the app stores (the Ledger sheet and the Receipts tree) lives in one Drive folder."
open_url "https://drive.google.com/drive/my-drive"
step "Create a folder named 'Expense Manager' (or open the one you already use), then open it."
step "Copy the ID from the address bar: it is the part after /folders/ in"
note "https://drive.google.com/drive/folders/<THIS-IS-THE-ID>"
ask_required GOOGLE_DRIVE_FOLDER_ID "Paste the folder ID (or the whole folder URL):"
GOOGLE_DRIVE_FOLDER_ID="${GOOGLE_DRIVE_FOLDER_ID##*/folders/}"
GOOGLE_DRIVE_FOLDER_ID="${GOOGLE_DRIVE_FOLDER_ID%%[?#]*}"
write_env GOOGLE_DRIVE_FOLDER_ID "$GOOGLE_DRIVE_FOLDER_ID"

# ── 2. Google Cloud project ──────────────────────────────────────────────
stage "Google Cloud: a project for the OAuth client and APIs"
say "The OAuth client, the Drive/Sheets APIs and the Gemini key all hang off one Cloud project."
open_url "https://console.cloud.google.com/projectcreate"
step "Name it 'Family-Expense-Manager' and click Create (or reuse a project you already have)."
step "Note the Project ID: the lowercase, hyphenated id shown under the name on the form and on the dashboard."
note "It is not saved anywhere; the next stages only use it to open console pages in the right project."
ask_required GCP_PROJECT_ID "Project ID:"

# ── 3. Enable APIs ───────────────────────────────────────────────────────
stage "Google Cloud: enable the Drive and Sheets APIs"
say "Both must be enabled on project '$GCP_PROJECT_ID' or every backend call fails with 403."
open_url "https://console.cloud.google.com/apis/library/drive.googleapis.com?project=$GCP_PROJECT_ID"
step "Click Enable on the Google Drive API page (if it says Manage, it is already enabled)."
pause "Drive API enabled? Press Enter."
open_url "https://console.cloud.google.com/apis/library/sheets.googleapis.com?project=$GCP_PROJECT_ID"
step "Click Enable on the Google Sheets API page."
pause "Sheets API enabled? Press Enter."

# ── 4. OAuth consent screen → production ─────────────────────────────────
stage "Google Cloud: OAuth consent screen, published to production"
warn "A project left in 'Testing' revokes its refresh tokens every 7 days. Publishing makes the token permanent."
say "Only you will ever consent on this screen, so you do not need to submit it for Google verification."
open_url "https://console.cloud.google.com/auth/overview?project=$GCP_PROJECT_ID"
step "If the console asks you to configure the app first: App name 'Family Expense Manager', your Gmail as"
step "  user support email, audience External, your Gmail as developer contact. Save; add no scopes or test users."
step "Then look for 'Publishing status'. In the Google Auth Platform layout it is on the Audience page; in the"
step "  older layout it is on the OAuth consent screen page. Click 'Publish app' and confirm 'Push to production'."
note "Google reshuffles this console often. If the page differs, look for 'Publishing status' / 'Publish app'"
note "under APIs & Services → OAuth consent screen, or Google Auth Platform → Audience."
if confirm "Does the publishing status now read 'In production'?"; then
  say "Good: refresh tokens minted from this project will not expire."
else
  warn "Not published: a refresh token minted now will stop working after 7 days."
  SKIPPED+=("Publish the OAuth consent screen (project $GCP_PROJECT_ID) to production, then redo the refresh-token stage")
  pause
fi

# ── 5. OAuth client ──────────────────────────────────────────────────────
stage "Google Cloud: OAuth client ID and secret"
open_url "https://console.cloud.google.com/apis/credentials?project=$GCP_PROJECT_ID"
step "Click '+ Create credentials' → 'OAuth client ID'. (If the console sends you to Google Auth Platform →"
step "  Clients instead, look for '+ Create client' there; the fields are the same.)"
step "Application type: Web application.  Name: Expense Manager Web Client."
step "Under 'Authorized redirect URIs' click '+ Add URI' and paste exactly (no trailing slash):"
note "https://developers.google.com/oauthplayground"
step "Click Create. A dialog shows the Client ID and the Client secret."
ask_required GOOGLE_CLIENT_ID "Paste the Client ID:"
[[ "$GOOGLE_CLIENT_ID" == *.apps.googleusercontent.com ]] \
  || warn "expected something ending in .apps.googleusercontent.com; double-check what you pasted"
ask_secret_required GOOGLE_CLIENT_SECRET "Paste the Client secret (hidden):"
write_env GOOGLE_CLIENT_ID "$GOOGLE_CLIENT_ID"
write_env GOOGLE_CLIENT_SECRET "$GOOGLE_CLIENT_SECRET"

# ── 6. Refresh token ─────────────────────────────────────────────────────
stage "OAuth Playground: mint the permanent refresh token"
say "The backend uses this token to act as your Google account on Drive and Sheets."
warn "If the consent screen is not yet 'In production' (stage 4), this token dies in 7 days."
open_url "https://developers.google.com/oauthplayground/"
step "Click the gear icon (OAuth 2.0 configuration) top-right → tick 'Use your own OAuth credentials'"
step "  → paste the Client ID and Client secret from the previous stage → Close."
step "In 'Step 1' on the left, scroll to the 'Input your own scopes' box and paste exactly:"
note "https://www.googleapis.com/auth/drive https://www.googleapis.com/auth/spreadsheets"
step "Click 'Authorize APIs'. Sign in with the Google account that owns the Expense Manager folder."
step "On 'Google hasn't verified this app': Advanced → 'Go to Family Expense Manager (unsafe)' → allow both."
step "In 'Step 2', click 'Exchange authorization code for tokens' and copy the refresh_token value (starts 1//)."
note "No refresh_token in the response? Revoke the app at https://myaccount.google.com/permissions and authorize again."
ask_secret_required GOOGLE_REFRESH_TOKEN "Paste the refresh_token (hidden):"
[[ "$GOOGLE_REFRESH_TOKEN" == 1//* ]] \
  || warn "refresh tokens normally start with 1//; make sure you did not paste the access token"
write_env GOOGLE_REFRESH_TOKEN "$GOOGLE_REFRESH_TOKEN"

# ── 7. Sheet ID (optional) ───────────────────────────────────────────────
stage "Google Sheets: Ledger spreadsheet ID (optional)"
say "Leave this blank: on the first pairing, Bootstrap creates 'Expenses_Database' inside the Drive folder."
say "Fill it only if you already have a Ledger spreadsheet the app should use instead."
open_url "https://drive.google.com/drive/folders/$GOOGLE_DRIVE_FOLDER_ID"
step "If a Ledger sheet already exists, open it and copy the ID from its URL: /spreadsheets/d/<THIS-IS-THE-ID>/edit"
note "On a re-run, Enter keeps a previously saved ID; to clear one, edit $ENV_FILE."
ask GOOGLE_SHEET_ID "Spreadsheet ID or URL (Enter to leave blank):"
GOOGLE_SHEET_ID="${GOOGLE_SHEET_ID##*/spreadsheets/d/}"
GOOGLE_SHEET_ID="${GOOGLE_SHEET_ID%%/*}"
GOOGLE_SHEET_ID="${GOOGLE_SHEET_ID%%[?#]*}"
write_env GOOGLE_SHEET_ID "$GOOGLE_SHEET_ID"

# ── 8. Gemini API key ────────────────────────────────────────────────────
stage "Google AI Studio: Gemini API key"
say "Receipt OCR calls Gemini with this key. Create it in project '$GCP_PROJECT_ID' so the billing you"
say "confirm in the next stage covers it."
open_url "https://aistudio.google.com/app/apikey"
step "Look for 'Create API key' on the API keys page (AI Studio moves this button around)."
step "When asked which Google Cloud project to create it in, pick '$GCP_PROJECT_ID'."
step "Copy the key (starts with AIza)."
ask_secret_required GEMINI_API_KEY "Paste the Gemini API key (hidden):"
[[ "$GEMINI_API_KEY" == AIza* ]] || warn "Gemini keys usually start with AIza; double-check what you pasted"
write_env GEMINI_API_KEY "$GEMINI_API_KEY"

# ── 9. Gemini billing ────────────────────────────────────────────────────
stage "Gemini: confirm billing is enabled on the key's project"
warn "Free-tier Gemini is 'Unpaid Services': Google may use receipt images to improve its products and"
warn "human reviewers may read them. Do not send real receipts through OCR until billing is on."
say "With billing enabled (paid tier; a small minimum prepay) prompts are not used for product improvement"
say "and only abuse-monitoring logs are kept, for 55 days."
open_url "https://ai.google.dev/gemini-api/docs/billing"
step "Follow the 'enable billing' instructions on that page. They lead either to AI Studio (look for a Plan /"
step "  'Set up billing' control next to project '$GCP_PROJECT_ID' on the API keys page) or to the Cloud"
step "  Console billing page for the project, opened next:"
open_url "https://console.cloud.google.com/billing?project=$GCP_PROJECT_ID"
step "Link an active billing account to '$GCP_PROJECT_ID'. AI Studio should then show the project on a paid tier."
if confirm "Is billing enabled on the project that owns the Gemini key?"; then
  say "Good: receipts are processed under the paid-tier data terms."
else
  warn "Not enabled: keep OCR unused (or test with dummy receipts) until billing is on."
  SKIPPED+=("Enable billing on the Gemini key's Cloud project ($GCP_PROJECT_ID) before scanning real receipts")
  pause
fi

# ── 10. Gemini model id ──────────────────────────────────────────────────
stage "Gemini: model id"
say "OCR uses gemini-3.5-flash-lite by default (document parsing; image and PDF input)."
say "gemini-3.8-flash is the higher-accuracy, pricier option. gemini-2.5-* is restricted to prior users"
say "and gemini-2.0-* is shut down, so do not pick those."
note "Current ids: https://ai.google.dev/gemini-api/docs/models"
ask GEMINI_MODEL "Model id (Enter for gemini-3.5-flash-lite):"
: "${GEMINI_MODEL:=gemini-3.5-flash-lite}"
write_env GEMINI_MODEL "$GEMINI_MODEL"

# ── 11. Family Access Code ───────────────────────────────────────────────
stage "Family Access Code"
say "Family members type this once to pair a phone (or scan the Admin's QR pair code instead)."
say "It must be at least 10 characters; the backend compares it in constant time and slows wrong guesses."
FAMILY_ACCESS_CODE=""
if [[ -f "$ENV_FILE" ]] && grep -qE "^FAMILY_ACCESS_CODE='..+'" "$ENV_FILE"; then
  say "An Access Code is already saved in $ENV_FILE."
  if confirm "Generate a new one? (already-paired devices stay paired; new devices need the new code)"; then
    FAMILY_ACCESS_CODE=""
  else
    FAMILY_ACCESS_CODE=$(_existing FAMILY_ACCESS_CODE)
  fi
fi
if [[ -z "$FAMILY_ACCESS_CODE" ]]; then
  FAMILY_ACCESS_CODE=$(openssl rand -hex 6)   # 12 characters, easy to type on a phone
  printf '\n  %sYour Family Access Code:%s  %s%s%s\n\n' "$BOLD" "$RESET" "$GREEN" "$FAMILY_ACCESS_CODE" "$RESET"
  warn "Shown once. Save it in your password manager now: the screen clears at the next stage."
  if ! confirm "Use this code?"; then
    while :; do
      ask_secret_required FAMILY_ACCESS_CODE "Type your own Access Code (hidden, 10+ characters):"
      (( ${#FAMILY_ACCESS_CODE} >= 10 )) && break
      warn "too short (${#FAMILY_ACCESS_CODE} characters): it needs at least 10"
    done
  fi
  pause "Saved it somewhere safe? Press Enter."
fi
write_env FAMILY_ACCESS_CODE "$FAMILY_ACCESS_CODE"

# ── 12. JWT secret ───────────────────────────────────────────────────────
stage "JWT secret"
say "Signs the year-long device sessions. Generated locally with openssl; it is never displayed."
JWT_SECRET=""
if [[ -f "$ENV_FILE" ]] && grep -qE "^JWT_SECRET='..+'" "$ENV_FILE"; then
  say "A JWT_SECRET is already saved in $ENV_FILE."
  warn "Rotating it logs every paired device out; each phone must pair again."
  if confirm "Rotate it anyway?"; then
    JWT_SECRET=""
  else
    JWT_SECRET=$(_existing JWT_SECRET)
  fi
fi
if [[ -z "$JWT_SECRET" ]]; then
  JWT_SECRET=$(openssl rand -base64 32)   # 32 random bytes, base64-encoded
  say "Generated a new 32-byte secret."
fi
write_env JWT_SECRET "$JWT_SECRET"

# ── 13. Vercel link ──────────────────────────────────────────────────────
stage "Vercel: link the project"
say "The env vars are pushed with the Vercel CLI, which needs $PROJECT_DIR linked to a Vercel project."
VERCEL_READY=0
if ! command -v vercel >/dev/null 2>&1 || ! vercel whoami >/dev/null 2>&1; then
  warn "vercel CLI not found or not logged in (npm i -g vercel; vercel login). Skipping the Vercel stages."
  SKIPPED+=("Vercel: 'vercel login', 'vercel link' in $PROJECT_DIR, then re-run this wizard to push the env vars")
elif [[ -f "$PROJECT_DIR/.vercel/project.json" ]]; then
  say "Already linked: $PROJECT_DIR/.vercel/project.json exists."
  VERCEL_READY=1
else
  LINK_ARGS=(--yes --project "$VERCEL_PROJECT")
  [[ -n "$VERCEL_SCOPE" ]] && LINK_ARGS+=(--scope "$VERCEL_SCOPE")
  say "Not linked yet. 'vercel link ${LINK_ARGS[*]}' links this folder to the Vercel project"
  say "'$VERCEL_PROJECT', creating it if none exists, and writes .vercel/project.json (git-ignored)."
  note "Another project name or team? Answer No and re-run with VERCEL_PROJECT=... VERCEL_SCOPE=... set"
  note "(saved values are kept)."
  note "vercel link may append '.env*' to .gitignore: undo that ('git checkout .gitignore'), or it hides .env.example."
  if confirm "Run 'vercel link ${LINK_ARGS[*]}' in $PROJECT_DIR now?"; then
    if vercel --cwd "$PROJECT_DIR" link "${LINK_ARGS[@]}"; then
      VERCEL_READY=1
    else
      warn "vercel link failed"
      SKIPPED+=("Vercel: 'vercel link' in $PROJECT_DIR, then re-run this wizard to push the env vars")
    fi
  else
    SKIPPED+=("Vercel: 'vercel link' in $PROJECT_DIR, then re-run this wizard to push the env vars")
  fi
fi

# ── 14. Vercel env vars ──────────────────────────────────────────────────
stage "Vercel: push the environment variables"
VERCEL_PUBLIC=(GOOGLE_DRIVE_FOLDER_ID GOOGLE_CLIENT_ID GOOGLE_SHEET_ID GEMINI_MODEL)
VERCEL_SECRET=(GOOGLE_CLIENT_SECRET GOOGLE_REFRESH_TOKEN GEMINI_API_KEY FAMILY_ACCESS_CODE JWT_SECRET)
if (( VERCEL_READY )); then
  say "Pushes every value saved in $ENV_FILE to the production and preview environments; existing"
  say "Vercel values with the same name are overwritten. Blank values (e.g. GOOGLE_SHEET_ID) are skipped."
  say "Secrets are stored as Sensitive: Vercel never shows them again, so $ENV_FILE is your copy."
  if confirm "Push $(( ${#VERCEL_PUBLIC[@]} + ${#VERCEL_SECRET[@]} )) variables to Vercel production and preview now?"; then
    for name in "${VERCEL_PUBLIC[@]}"; do
      if [[ -z "${!name}" ]]; then note "skipping $name (blank)"; continue; fi
      for environment in production preview; do
        push_vercel_env "$name" "${!name}" "$environment"
      done
    done
    for name in "${VERCEL_SECRET[@]}"; do
      for environment in production preview; do
        push_vercel_env "$name" "${!name}" "$environment" --sensitive
      done
    done
    note "Next: redeploy ('vercel --prod', or push to the connected Git branch) so the new values take effect."
    pause
  else
    SKIPPED+=("Push the $ENV_FILE values to Vercel: vercel env add NAME --environment production (and preview) for each NAME")
  fi
else
  say "Vercel is not ready (see the previous stage), so nothing was pushed."
  pause
fi

finish
}

run_wizard "$@"; exit
